corrected_code:
@Controller('api/v2/webhooks')
@UseGuards(ApiKeyAuthGuard)
export class WebhookConfigController {
  constructor(@Inject('DRIZZLE') private readonly db: DrizzleClient) {}

  @Delete(':webhookId')
  async removeWebhook(@Param('webhookId') webhookId: string, @Req() req: RequestWithApiKey) {
    const result = await this.db.delete(webhooksTable)
      .where(and(eq(webhooksTable.id, webhookId), eq(webhooksTable.orgId, req.auth.orgId)))
      .returning();
    if (result.length === 0) throw new ForbiddenException('Webhook not found or access denied');
    return { deleted: true, webhookId };
  }
}
